with open('region.fasta') as f:
    hdr=f.readline().strip()
    for line in f:
        seq.append(line.strip())
s=''.join(seq).upper()
L=len(s)
comp=str.maketrans('ACGT','TGCA')
rc=s.translate(comp)[::-1]

stops=set('TAA TAG TGA'.split())
def orfs(seq,label):
    out=[]
    n=len(seq)
    for frame in range(3):
        i=frame
        start=None
        while i<n-2:
            c=seq[i:i+3]
            if c=='ATG' and start is None:
                start=i
            elif c in stops:
                if start is not None:
                    out.append((start,i+3,label,frame+1))
                    start=None
                else:
                    # stop->stop fragment with no ATG
                    pass
            i+=3
        if start is not None:
            out.append((start,None,label,frame+1))
    return out

all_o=orfs(s,'+')+orfs(rc,'-')
rows=[]
for st,en,lab,fr in all_o:
    if en is None:
        en=L
    length=en-st
    aa=(en-st)//3-1
    rows.append((lab,fr,st+1,en,length,aa,[st, en]))
rows.sort(key=lambda r:(r[4]),reverse=True)
print('frame-strand, start, end, bp, aa (top 25 by length, ONLY complete ATG->stop):')
for lab,fr,st,en,length,aa,_ in rows:
    if aa>=30:
        print(f'{lab}{fr}  {st:5d}-{en:5d}  {length:4d} bp  {aa:4d} aa')
