comp=str.maketrans('ACGT','TGCA')
s=''.join(x.strip() for x in open('region.fasta').read().splitlines()[1:])
def palin(x,stem=7,loopmin=3,loopmax=12):
    hits=[]
    for i in range(len(x)-2*stem-loopmax):
        for loop in range(loopmin,loopmax+1):
            a=x[i:i+stem]; b=x[i+stem+loop:i+2*stem+loop]
            if a.translate(comp)[::-1]==b: hits.append((i+1,i+2*stem+loop-1,loop))
    return hits
print('len hits stem8 whole:',len(palin(s,8)))
print('sample:',palin(s,8)[:5])
# count how many are in / near the ORF boundaries
def hairpin_score(a,b):
    # crude
    pairs=sum(3 if x=='G' and y=='C' or x=='C' and y=='G' else 2 if x=='A' and y=='T' or x=='T' and y=='A' else 0 for x,y in zip(a,b))
    return pairs
best=None
minloop,maxloop=4,10
for i in range(0,len(s)-2*8-maxloop):
    for loop in range(minloop,maxloop+1):
        a=s[i:i+8]; b=s[i+8+loop:i+16+loop]
        sc=hairpin_score(a,b)
        if best is None or sc>best[0]:
            best=(sc,i+1,i+16+loop-1,loop,a,b)
print('best 8-stem hairpin score:',best)
